        "1:\n\t"
        "ldr     x4, [%0], #8\n\t"       // 读取 lhs[i]，指针 +8
        "ldr     x5, [%1], #8\n\t"       // 读取 rhs[i]，指针 +8
        "adcs    x6, x4, x5\n\t"         // 带 C 标志加法，同时产生新的 C 标志
        "str     x6, [%2], #8\n\t"       // 写入 result[i]，指针 +8

