        }

    } while (test_time_condition(test));

    return EXIT_SUCCESS;
}

static int fisttp_arm_finish(struct test *test) {
    auto *shared_data = static_cast<SharedTestData*>(test->data);
    if (shared_data) {
        delete shared_data;
    }
